// Command beta-deployment-record writes the secret-free packaging bill of materials.
package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"flag"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"

	"github.com/Standard-Syntax/basic/go/internal/approval"
	"github.com/Standard-Syntax/basic/go/internal/beta"
	"github.com/Standard-Syntax/basic/go/internal/dockerengine"
	"github.com/Standard-Syntax/basic/go/internal/execution"
	"github.com/Standard-Syntax/basic/go/internal/migration"
	"github.com/Standard-Syntax/basic/go/internal/publication"
	"github.com/Standard-Syntax/basic/go/internal/reasoning/gateway"
	"github.com/Standard-Syntax/basic/go/internal/registry"
	"github.com/Standard-Syntax/basic/go/internal/verification"
	"github.com/Standard-Syntax/basic/go/internal/workflow"
)

func main() {
	os.Exit(mainExit())
}

func mainExit() int {
	configPath := flag.String("config", "", "absolute beta deployment path")
	outputPath := flag.String("output", "", "absolute output path")
	flag.Parse()
	deployment, err := beta.LoadDeployment(*configPath)
	if err != nil || !filepath.IsAbs(*outputPath) {
		return fail()
	}
	record, err := buildRecord(context.Background(), &deployment)
	if err != nil {
		return fail()
	}
	body, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return fail()
	}
	body = append(body, '\n')
	if err := os.WriteFile(*outputPath, body, 0o600); err != nil {
		return fail()
	}
	return 0
}

func fail() int {
	fmt.Fprintln(os.Stderr, "deployment record generation failed")
	return 1
}

func buildRecord(ctx context.Context, deployment *beta.Deployment) (beta.DeploymentRecord, error) {
	engine, err := dockerengine.NewFromEnvironment()
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	defer engine.Close()
	for _, image := range []string{deployment.Images.API, deployment.Images.Workflow,
		deployment.Images.Execution, deployment.Images.Verification} {
		actual, err := engine.ImageID(ctx, image)
		if err != nil || actual != image {
			return beta.DeploymentRecord{}, fmt.Errorf("image identity mismatch")
		}
	}
	migrations, err := migration.Describe(workflow.MigrationSource(), registry.MigrationSource(),
		gateway.MigrationSource(), execution.MigrationSource(), verification.MigrationSource(),
		approval.MigrationSource(), publication.MigrationSource())
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	migrationBody, _ := json.Marshal(migrations)
	configDigest, err := deployment.Digest()
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	gitVersion, err := command("git", "--version")
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	manifests, err := directoryDigests(deployment.Mounts.Manifests)
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	prompts, err := directoryDigests(deployment.Mounts.Prompts)
	if err != nil {
		return beta.DeploymentRecord{}, err
	}
	return beta.DeploymentRecord{SchemaVersion: beta.DeploymentRecordVersion,
		SourceCommit: deployment.SourceCommit, MigrationDigest: digest(migrationBody),
		ManifestDigests: manifests, PromptDigests: prompts, Images: deployment.Images,
		GitVersion: gitVersion, GoVersion: runtime.Version(), ToolchainVersion: runtime.Version(),
		ConfigurationDigest: configDigest}, nil
}

func directoryDigests(root string) (map[string]string, error) {
	paths := make([]string, 0)
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !entry.IsDir() {
			paths = append(paths, path)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(paths)
	result := make(map[string]string, len(paths))
	for _, path := range paths {
		body, err := os.ReadFile(path)
		if err != nil {
			return nil, err
		}
		relative, _ := filepath.Rel(root, path)
		result[filepath.ToSlash(relative)] = digest(body)
	}
	return result, nil
}

func digest(body []byte) string { sum := sha256.Sum256(body); return hex.EncodeToString(sum[:]) }
func command(name string, args ...string) (string, error) {
	body, err := exec.Command(name, args...).CombinedOutput()
	return strings.TrimSpace(string(body)), err
}
package beta

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"os"
	"regexp"
)

const DeploymentVersion = "beta_deployment.v1"

var immutableImagePattern = regexp.MustCompile(`^sha256:[0-9a-f]{64}$`)

// Deployment is the strict, secret-free operator envelope for one exact beta
// image set. Sensitive values remain in separately mounted owner-only files.
type Deployment struct {
	SchemaVersion     string                `json:"schema_version"`
	SourceCommit      string                `json:"source_commit"`
	Policy            Policy                `json:"beta_policy"`
	Services          DeploymentServices    `json:"services"`
	Images            DeploymentImages      `json:"images"`
	Mounts            DeploymentMounts      `json:"mounts"`
	Credentials       DeploymentCredentials `json:"credentials"`
	DockerSocketGroup int                   `json:"docker_socket_group"`
}

type DeploymentServices struct {
	APIConfig      string `json:"api_config"`
	WorkflowConfig string `json:"workflow_config"`
	APIListen      string `json:"api_listen"`
	WorkflowListen string `json:"workflow_listen"`
}

type DeploymentImages struct {
	API          string `json:"api_service"`
	Workflow     string `json:"workflow_service"`
	Execution    string `json:"execution_worker"`
	Verification string `json:"verification_worker"`
}

type DeploymentMounts struct {
	Repository    string `json:"repository"`
	CAS           string `json:"cas"`
	Worktrees     string `json:"worktrees"`
	Verification  string `json:"verification"`
	Manifests     string `json:"manifests"`
	Prompts       string `json:"prompts"`
	Configuration string `json:"configuration"`
}

type DeploymentCredentials struct {
	MiniMax          string `json:"minimax"`
	DatabasePassword string `json:"database_password"`
	GitHub           string `json:"github,omitempty"`
	GitPush          string `json:"git_push,omitempty"`
}

func LoadDeployment(path string) (Deployment, error) {
	if !CleanAbsolute(path) {
		return Deployment{}, errors.New("deployment path must be clean and absolute")
	}
	file, err := os.Open(path)
	if err != nil {
		return Deployment{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, 1<<20))
	decoder.DisallowUnknownFields()
	var value Deployment
	if err := decoder.Decode(&value); err != nil {
		return Deployment{}, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return Deployment{}, errors.New("deployment has trailing content")
	}
	if err := value.Validate(); err != nil {
		return Deployment{}, err
	}
	return value, nil
}

func (d *Deployment) Validate() error { // skipcq: GO-R1005 -- strict fail-closed envelope validation
	if d.SchemaVersion != DeploymentVersion || !regexp.MustCompile(`^[0-9a-f]{40}$`).MatchString(d.SourceCommit) ||
		d.DockerSocketGroup <= 0 || d.Services.APIListen == "" || d.Services.WorkflowListen == "" {
		return errors.New("invalid beta deployment identity")
	}
	if err := d.Policy.Validate(); err != nil {
		return errors.New("invalid beta deployment policy")
	}
	images := []string{d.Images.API, d.Images.Workflow, d.Images.Execution, d.Images.Verification}
	for _, image := range images {
		if !immutableImagePattern.MatchString(image) {
			return errors.New("deployment images must be immutable IDs")
		}
	}
	if d.Policy.Images.Execution != d.Images.Execution || d.Policy.Images.Verification != d.Images.Verification {
		return errors.New("deployment worker images do not match beta policy")
	}
	paths := []string{d.Services.APIConfig, d.Services.WorkflowConfig, d.Mounts.Repository,
		d.Mounts.CAS, d.Mounts.Worktrees, d.Mounts.Verification, d.Mounts.Manifests,
		d.Mounts.Prompts, d.Mounts.Configuration, d.Credentials.MiniMax, d.Credentials.DatabasePassword}
	if d.Credentials.GitHub != "" {
		paths = append(paths, d.Credentials.GitHub)
	}
	if d.Credentials.GitPush != "" {
		paths = append(paths, d.Credentials.GitPush)
	}
	for _, path := range paths {
		if !CleanAbsolute(path) {
			return errors.New("deployment paths must be clean and absolute")
		}
	}
	if d.Policy.Repository.Root != d.Mounts.Repository {
		return errors.New("deployment repository does not match beta policy")
	}
	return nil
}

func (d *Deployment) Digest() (string, error) {
	body, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(body)
	return hex.EncodeToString(sum[:]), nil
}
package beta

import (
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"slices"
)

const (
	CanaryOwner      = "Standard-Syntax"
	CanaryRepository = "basic-beta-canary"
	CanaryBaseBranch = "main"
)

var canaryCredentialPathPattern = regexp.MustCompile(`^/[A-Za-z0-9_./-]+$`)

// Config is the shared strict configuration envelope used by production
// preflight and the separately credentialed GitHub canary commands. Secret
// values are never members of the envelope; only mounted credential paths are.
type Config struct {
	DatabaseURL                   string `json:"database_url"`
	ArtifactRoot                  string `json:"artifact_root"`
	WorktreeRoot                  string `json:"worktree_root"`
	VerificationWorkspaceRoot     string `json:"verification_workspace_root"`
	ProviderCredentialEnvironment string `json:"provider_credential_environment"`
	PublicationCredentialFile     string `json:"publication_credential_file"`
	GitPushCredentialFile         string `json:"git_push_credential_file,omitempty"`
	Policy                        Policy `json:"beta_policy"`
}

func LoadConfig(name string) (Config, error) {
	if !CleanAbsolute(name) {
		return Config{}, errors.New("config path must be clean and absolute")
	}
	file, err := os.Open(name)
	if err != nil {
		return Config{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, 1<<20))
	decoder.DisallowUnknownFields()
	var value Config
	if err := decoder.Decode(&value); err != nil {
		return Config{}, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
		return Config{}, errors.New("trailing configuration")
	}
	if value.DatabaseURL == "" || value.ProviderCredentialEnvironment == "" ||
		!CleanAbsolute(value.ArtifactRoot) || !CleanAbsolute(value.WorktreeRoot) ||
		!CleanAbsolute(value.VerificationWorkspaceRoot) ||
		!CleanAbsolute(value.PublicationCredentialFile) ||
		(value.GitPushCredentialFile != "" && !CleanAbsolute(value.GitPushCredentialFile)) {
		return Config{}, errors.New("incomplete preflight configuration")
	}
	if err := value.Policy.Validate(); err != nil {
		return Config{}, err
	}
	return value, nil
}

// ValidateCanary narrows the general beta policy to the one operator-owned
// canary repository and fixture. It intentionally does not accept aliases or
// additional readable/writable paths.
func (c Config) ValidateCanary() error {
	if c.Policy.Repository.Owner != CanaryOwner ||
		c.Policy.Repository.Name != CanaryRepository ||
		c.Policy.Repository.Remote != "origin" ||
		c.Policy.Repository.RemoteURL != "git@github.com:Standard-Syntax/basic-beta-canary.git" ||
		c.Policy.Repository.BaseBranch != CanaryBaseBranch ||
		c.ProviderCredentialEnvironment != "ANTHROPIC_API_KEY" ||
		c.GitPushCredentialFile == "" ||
		!canaryCredentialPathPattern.MatchString(c.GitPushCredentialFile) ||
		!slices.Equal(c.Policy.Paths.Readable, []string{"Makefile", "add.go", "add_test.go"}) ||
		!slices.Equal(c.Policy.Paths.Writable, []string{"add.go"}) ||
		!slices.Equal(c.Policy.Paths.Prohibited, []string{"Makefile", "add_test.go"}) ||
		!slices.Equal(c.Policy.TrustedChecks, []string{"make-check-v1"}) ||
		c.Policy.Limits.MaximumChangedFiles != 1 {
		return errors.New("configuration does not match the dedicated canary policy")
	}
	return nil
}

