	var completedBeforeRestart int
	if err := pool.QueryRow(t.Context(), `SELECT count(*) FROM runtime_stage_jobs
		WHERE run_id=$1 AND state='COMPLETED'`, runID).Scan(&completedBeforeRestart); err != nil {
		t.Fatal(err)
